-- Stand-in base schema for a THROWAWAY local Postgres (columns from src/types/supabase.ts). Not for any real database.
CREATE ROLE service_role NOLOGIN; CREATE ROLE anon NOLOGIN; CREATE ROLE authenticated NOLOGIN;
CREATE SCHEMA auth;
CREATE TABLE auth.users (id uuid PRIMARY KEY);
CREATE FUNCTION auth.uid() RETURNS uuid LANGUAGE sql STABLE AS $$ SELECT NULLIF(current_setting('request.jwt.sub', true), '')::uuid $$;
GRANT USAGE ON SCHEMA auth, public TO service_role, authenticated, anon;
CREATE TABLE public.deck_folders (id integer PRIMARY KEY, name text, user_id uuid);
CREATE TABLE public.decks (
  id integer PRIMARY KEY, allocate boolean NOT NULL DEFAULT true, bracket text, build_id text, card_count integer, colour_identity text,
  commander_id text, commander_name text, commander_scryfall_id text, deck_type text, folder_id integer REFERENCES deck_folders(id),
  format text, is_active boolean NOT NULL DEFAULT true, is_precon_mod boolean, last_synced_at timestamptz, name text NOT NULL,
  precon_url text, raw_json text, source_platform text, source_url text, status text NOT NULL DEFAULT 'active', user_id uuid NOT NULL REFERENCES auth.users(id));
CREATE TABLE public.deck_cards (
  id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, card_name text NOT NULL, categories text, command_zone_role text,
  copy_id integer, dead_weight_flag text, dead_weight_reason text, deck_id integer NOT NULL REFERENCES decks(id) ON DELETE CASCADE,
  is_commander boolean, ownership_status text, placement_source text, proxy_of_deck_id integer, quantity integer, requested_finish text,
  requested_language text, generic_sleeved boolean NOT NULL DEFAULT false, is_generic boolean NOT NULL DEFAULT false, scryfall_id text,
  set_code text, tags text, user_id uuid NOT NULL);
CREATE TABLE public.deck_strategy (
  deck_id integer NOT NULL REFERENCES decks(id) ON DELETE CASCADE, user_id uuid NOT NULL, bracket integer, budget_ceiling numeric, budget_mode text,
  format_rules text, frustration text, health_overrides text, strategy_notes text, table_context text, updated_at timestamptz, win_condition text,
  UNIQUE (deck_id));   -- APPROXIMATE: the app upserts onConflict deck_id, so a unique key on deck_id is assumed
CREATE TABLE public.deck_versions (id integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY, deck_id integer NOT NULL REFERENCES decks(id) ON DELETE CASCADE,
  user_id uuid NOT NULL, version_number integer NOT NULL DEFAULT 1, trigger_type text NOT NULL DEFAULT 'x', card_count integer NOT NULL DEFAULT 0,
  cards_snapshot jsonb NOT NULL DEFAULT '[]', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.user_cards (id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, card_name text NOT NULL, color_identity text, created_at timestamptz,
  oracle_id text NOT NULL, type_line text, user_id uuid NOT NULL);
CREATE TABLE public.user_locations (id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, deck_id integer, name text, is_default boolean NOT NULL DEFAULT false,
  type text NOT NULL DEFAULT 'box', user_id uuid NOT NULL);
CREATE TABLE public.user_copies (id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, card_id integer NOT NULL, condition text, finish text,
  is_proxy boolean NOT NULL DEFAULT false, location_id integer, in_hand boolean NOT NULL DEFAULT false, missing boolean NOT NULL DEFAULT false,
  printing_id text, source_tag text, user_id uuid NOT NULL);
-- move_items: the Picklist steps (the real migration 20261113100100 needs more tables; only the deck references matter here)
CREATE TABLE public.move_items (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, user_id uuid NOT NULL, list_id uuid NOT NULL, copy_id integer,
  card_name text NOT NULL, from_deck_id integer REFERENCES decks(id) ON DELETE SET NULL, from_deck_card_id integer REFERENCES deck_cards(id) ON DELETE SET NULL,
  to_deck_card_id integer REFERENCES deck_cards(id) ON DELETE SET NULL, to_deck_id integer REFERENCES decks(id) ON DELETE SET NULL,
  to_location_id integer, state text NOT NULL DEFAULT 'to_find');
GRANT ALL ON ALL TABLES IN SCHEMA public TO service_role;
-- stand-in for the live helper routine (plain delete of the slot; the real one also releases a copy)
CREATE FUNCTION public.remove_deck_card_with_release(p_deck integer, p_slot integer, p_user uuid) RETURNS jsonb LANGUAGE plpgsql AS $$
BEGIN DELETE FROM deck_cards WHERE id = p_slot AND deck_id = p_deck AND user_id = p_user; RETURN '{}'::jsonb; END $$;
-- Added for the roles tests: stand-in for the reference printings table (live columns scryfall_id uuid PK, oracle_id uuid; other columns not needed here).
CREATE TABLE public.ref_printings (scryfall_id uuid PRIMARY KEY, oracle_id uuid NOT NULL, name text);
CREATE INDEX ref_printings_oracle ON public.ref_printings (oracle_id);
GRANT ALL ON public.ref_printings TO service_role;
